import java.util.Scanner;

public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long number = sc.nextLong();
    long answer = process(number);
    System.out.println(answer);
  }

  public static long process(long n) {
    if (n <= 6) {
      return n;
    }
    long digits = getDigitsCount(n);
    long base = generateOnes(digits);
    long nextBase = generateOnes(digits + 1);
    if (n == base) {
      return digits;
    }
    long resLower = process(n % base) + (n / base) * digits;
    long resUpper = Long.MAX_VALUE;
    if (nextBase - n < n) {
      resUpper = process(nextBase - n) + generateDigits(nextBase);
    }
    return Math.min(resLower, resUpper);
  }

  public static long getDigitsCount(long n) {
    return (long) Math.floor(Math.log10(n)) + 1;
  }

  public static long generateOnes(long count) {
    long res = 0;
    for (int i = 0; i < count; i++) {
      res = res * 10 + 1;
    }
    return res;
  }

  public static long generateDigits(long n) {
    return getDigitsCount(n);
  }
