def main():
    number = int(input())
    answer = process(number)
    print(answer)

def process(n):
    if n <= 6:
        return n
    digits = getDigitsCount(n)
    base = generateOnes(digits)
    nextBase = generateOnes(digits + 1)
    if n == base:
        return digits
    resLower = process(n % base) + (n // base) * digits
    resUpper = float('inf')
    if nextBase - n < n:
        resUpper = process(nextBase - n) + generateDigits(nextBase)
    return min(resLower, resUpper)

def getDigitsCount(n):
    return math.floor(math.log10(n)) + 1

def generateOnes(count):
    res = 0
    for _ in range(count):
        res = res * 10 + 1
    return res

def generateDigits(n):
    return getDigitsCount(n)

